#!/usr/bin/env bash
# In-repo copy for tests/doctor_runner.rs (unit U0, 2026-10-14). Source: the review package,
# local/doctor/tutorial/run-doctor-demo.sh. Changes from the source are marked U0-EDIT. Run through
# `cargo test --test doctor_runner`, or scripts/behaviour-lock.sh doctor to compare two binaries.
# evnx doctor demo runner (DR0-DR10). Non-interactive (no terminal), safe: each scene runs in its own temp folder.
# Usage: EVNX=/path/to/evnx ./run-doctor-demo.sh [DR5 ...]
# "KNOWN" lines mark behaviour logged as an issue in the review (22-doctor.md); they show 0.10.0 as it is today.
# Real git repositories are used where git decides the answer (an empty .git folder is not a repository).
# Nothing here touches the network. All values are synthetic.
set -u
EVNX="${EVNX:-evnx}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DEMO_ROOT="${DEMO_ROOT:-$(mktemp -d)}"
export NO_COLOR=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
unset EVNX_PASSWORD EVNX_OUTPUT_JSON EVNX_AUTO_FIX
pass=0; fail=0
run() { echo; echo "\$ ${*/#$EVNX/evnx}"; "$@" > "$DEMO_ROOT/.out" 2>"$DEMO_ROOT/.err" </dev/null; local rc=$?; cat "$DEMO_ROOT/.out"; [ -s "$DEMO_ROOT/.err" ] && { echo "[stderr]"; cat "$DEMO_ROOT/.err"; }; echo "[exit $rc]"; LAST=$rc; }
expect() { if [ "$LAST" -eq "$1" ]; then pass=$((pass+1)); echo "  ok: $2 (exit $1)"; else fail=$((fail+1)); echo "  MISMATCH: $2 expected exit $1, got $LAST"; fi; }
check() { if eval "$1"; then pass=$((pass+1)); echo "  ok: $2"; else fail=$((fail+1)); echo "  MISMATCH: $2"; fi; }
scene() { echo; echo "================ $1 ================"; D="$DEMO_ROOT/$1"; rm -rf "$D"; mkdir -p "$D"; cd "$D" || exit 1; }
repo() { git init -q . && git config user.email demo@example.com && git config user.name demo && git config commit.gpgsign false; }
commit() { git add -A >/dev/null 2>&1; git commit -q -m "$1" >/dev/null 2>&1; }
good_ignore() { printf '.env*\n!.env.example\n!.env.sample\n!.env.template\n' > .gitignore; }
healthy() { repo; printf 'DB_URL=postgres://user:pw@db.internal/app\nPORT=8080\n' > .env; chmod 600 .env; printf 'DB_URL=\nPORT=\n' > .env.example; good_ignore; commit init; }
mode() { stat -c '%a' "$1"; }

DR0() { scene DR0; healthy; run "$EVNX" --version; run "$EVNX" doctor --help; check '! "$EVNX" doctor --help | grep -q "Exit codes"' "KNOWN D-118: --help has no 'Exit codes' section (decided: it gets one; this check then flips)"; run "$EVNX" doctor --format yaml; expect 2 "unknown format is exit 2 'No verdict'"; run "$EVNX" doctor nowhere; expect 2 "missing directory: exit 2, not a clean result"; touch afile; run "$EVNX" doctor afile; expect 2 "a file is not a directory: exit 2"; run "$EVNX" doctor . --path .; expect 2 "positional and --path conflict"; }
DR1() { scene DR1; healthy; run "$EVNX" doctor; expect 0 "healthy project, real repo: exit 0"; run "$EVNX" doctor --verbose; expect 0 "verbose shows the ticks"; run "$EVNX" doctor --format json; expect 0 "json"; check '"$EVNX" doctor --format json 2>/dev/null | python3 -c "import json,sys; d=json.load(sys.stdin); assert d[\"summary\"][\"errors\"]==0 and len(d[\"checks\"])==5"' "JSON on stdout only: 5 checks, 0 errors"; check '"$EVNX" doctor 2>/dev/null | grep -c $'"'"'\033'"'"' | grep -qx 0' "no colour escapes when piped"; }
DR2() { scene DR2; repo; printf 'AWS=AKIA4OZRMFJ3VREALKEY\n' > .env; chmod 644 .env; run "$EVNX" doctor; expect 1 ".env not ignored and mode 644: errors, exit 1"; run "$EVNX" doctor --fix; expect 0 "--fix repairs both and exits 0"; run cat .gitignore; echo "KNOWN I-168: bare lines, no evnx section header (init writes a headed section)"; check '[ "$(mode .env)" = 600 ]' ".env is now 600"; check '! grep -q "evnx generated" .gitignore' "KNOWN I-168: no section header written by doctor"; run "$EVNX" doctor; expect 0 "healthy without --fix"; echo "KNOWN I-165: --fix printed no 'Fixed:' lines (decided S-D1: it will list each change)"; }
DR3() { scene DR3; healthy; echo 'KEY=1' >> .env; git add -f .env >/dev/null; git commit -q -m "oops: commit .env"; run git ls-files .env; run "$EVNX" doctor; expect 1 "KNOWN I-157: committed .env is reported as 'NOT in .gitignore'; decided: 'tracked by git' error with git rm --cached"; run "$EVNX" doctor --fix; expect 0 "KNOWN I-156/I-157: --fix reports it fixed and exits 0"; run "$EVNX" doctor; expect 1 "...and the next plain run still fails: nothing was repaired"; run git ls-files .env; }
DR4() { scene DR4; healthy; printf '.env*\n!.env\n' > .gitignore; commit gi; run "$EVNX" doctor; expect 1 ".env* then !.env: .env is exposed"; run "$EVNX" doctor --fix; expect 0 "KNOWN I-156: --fix claims success; the rule that exposes .env is still there"; run cat .gitignore; run "$EVNX" doctor; expect 1 "still exposed on the next run; decided (DEC-D1): verify after fix, exit 1"; }
DR5() { scene DR5; healthy; printf '.env\n' > .gitignore; commit gi; printf 'use flake\n' > .envrc; run "$EVNX" doctor; expect 1 "KNOWN I-173: a direnv .envrc is a security error; decided: .envrc is not an env file"; printf 'hello\n' > .environment; printf 'notes\n' > .env-notes.md; run "$EVNX" doctor; expect 1 "KNOWN I-173: .environment and .env-notes.md parsed as dotenv"; rm .envrc .environment .env-notes.md; cp .env .env.bak; cp .env .env.backup; run "$EVNX" doctor; expect 1 "KNOWN I-160: the plaintext copy .env.bak is checked and flagged..."; check '! "$EVNX" doctor 2>&1 | grep -q "env.backup"' "KNOWN I-160: ...but the same copy named .env.backup is skipped by name and never mentioned; decided: look inside, warn on plaintext copies"; }
DR6() { scene DR6; healthy; printf 'P=1\n' > .env.production; chmod 644 .env.production; run "$EVNX" doctor; expect 0 "KNOWN I-158: .env.production at 644 is not mentioned (only .env is checked); decided: every env file"; chmod 700 .env; run "$EVNX" doctor; expect 0 "KNOWN I-170: mode 700 is a warning (exit 0); decided: no group/other access passes"; chmod 644 .env; run "$EVNX" doctor --fix; check '[ "$(mode .env)" = 600 ] && [ "$(mode .env.production)" = 644 ]' "--fix changes .env only; .env.production stays 644 (decided: every flagged env file)"; mkdir ../outside-DR6 2>/dev/null; printf 'S=1\n' > ../outside-DR6/real.env; chmod 644 ../outside-DR6/real.env; rm .env; ln -s ../outside-DR6/real.env .env; run "$EVNX" doctor; echo "KNOWN I-159: a symlinked .env is not seen by env_file"; run "$EVNX" doctor --fix; check '[ "$(mode ../outside-DR6/real.env)" = 600 ]' "KNOWN I-159: --fix chmod'ed the target OUTSIDE the project (decided: only inside the project)"; }
DR7() { scene DR7; healthy; printf 'GOOD=1\n!!bad one\nALSO=2\n@@bad two\n# fine\n%%%%bad three\n' > .env; chmod 600 .env; run "$EVNX" doctor; expect 0 "KNOWN I-161: three bad lines are only a warning, exit 0; decided: errors, exit 1"; run "$EVNX" doctor --strict; expect 1 "--strict makes the warning fail"; printf 'export A=1\nP="-----BEGIN\nMIIE\n-----END"\nB=2\n' > .env; run "$EVNX" doctor; expect 0 "export prefix and multi-line value are valid (parser agreement)"; printf 'P="never closed\nB=2\n' > .env; run "$EVNX" doctor; expect 0 "KNOWN I-161: unterminated quote is a warning"; printf 'MY-KEY=1\n' > .env; run "$EVNX" doctor; echo "dashed key: invalid for doctor and for the parser (consistent)"; }
DR8() { scene DR8; mkdir empty && cd empty; run "$EVNX" doctor; expect 0 "KNOWN I-162: an empty directory exits 0; decided: exit 2 'nothing to diagnose'"; cd ..; mkdir tpl && cd tpl && repo && printf 'A=\n' > .env.example && commit t; run "$EVNX" doctor; expect 0 "KNOWN I-162: template but no .env is a warning; decided: error, exit 1"; run "$EVNX" doctor --strict; expect 1 "...--strict makes it fail"; cd ..; mkdir broken && cd broken && printf 'A=1\n' > .env && chmod 600 .env && mkdir requirements.txt; run "$EVNX" doctor; expect 2 "KNOWN I-163: a directory named requirements.txt aborts the run: bare OS error, no check name, no path, no summary; decided: 'could not run' entry, rest finish, exit 2"; }
# U0-EDIT (2026-10-14): DR9 -q check rewritten: 0.10.1 made -q hide the banner; the residual is still locked.
# U1-EDIT (2026-10-14): DR9 -q check flipped on purpose: a healthy project prints nothing under -q (I-164).
DR9() { scene DR9; healthy; "$EVNX" -q doctor > q.out 2>&1; "$EVNX" doctor > n.out 2>&1; check '[ ! -s q.out ] && [ -s n.out ]' "I-164 fixed: -q doctor on a healthy project prints nothing; the report still prints when there is a finding"; run env EVNX_OUTPUT_JSON=1 "$EVNX" doctor; expect 0 "EVNX_OUTPUT_JSON=1 gives JSON"; "$EVNX" doctor --format pretty > p.out 2>/dev/null; EVNX_OUTPUT_JSON=1 "$EVNX" doctor --format pretty > p2.out 2>/dev/null; check 'cmp -s p.out p2.out' "explicit --format pretty beats EVNX_OUTPUT_JSON"; run "$EVNX" doctor --format text; expect 0 "hidden alias --format text is accepted (decided: stays)"; printf 'AWS=1\n' > .env; chmod 644 .env; rm .gitignore; commit x; run env EVNX_AUTO_FIX=1 "$EVNX" doctor; expect 0 "KNOWN I-167: EVNX_AUTO_FIX=1 repairs with no notice; decided: stderr notice"; check '[ "$(mode .env)" = 600 ]' "the file was changed"; }
DR10() { scene DR10; repo; printf 'A=1\n' > .env; chmod 600 .env; good_ignore; commit i; for f in "pyproject.toml:[tool.poetry]" "Pipfile:x" "requirements.txt:flask" "package.json:{}" "Cargo.toml:[package]" "go.mod:module x" "composer.json:{}"; do rm -f poetry.lock pyproject.toml Pipfile requirements.txt package.json Cargo.toml go.mod composer.json; printf '%s\n' "${f#*:}" > "${f%%:*}"; printf '%-18s -> ' "${f%%:*}"; "$EVNX" doctor --verbose 2>&1 | grep -iE "detected|^Error" | head -1; done; echo "KNOWN I-175: the Pipfile line above is an Error, not a detection"; rm -f pyproject.toml Pipfile requirements.txt package.json Cargo.toml go.mod composer.json; printf '[packages]\nflask="*"\n' > Pipfile; run "$EVNX" doctor; expect 2 "KNOWN I-175 (High): a Pipfile-only project (no pyproject.toml) aborts the whole run: 'No such file or directory', exit 2; decided: read the file that defines the type, never abort"; rm Pipfile; : > poetry.lock; run "$EVNX" doctor; expect 2 "KNOWN I-175: a poetry.lock-only project aborts the same way"; rm poetry.lock; rm -f Pipfile requirements.txt package.json Cargo.toml go.mod composer.json pyproject.toml; printf 'flask\n' > requirements.txt; printf '{}\n' > package.json; run "$EVNX" doctor --verbose; echo "KNOWN: only the first match is reported (decided: every detected type)"; rm requirements.txt package.json; printf 'FROM scratch\nCOPY . .\n' > Dockerfile; run "$EVNX" doctor --verbose; expect 0 "KNOWN S-D5: Dockerfile with COPY . . and no .dockerignore is 'Found: Dockerfile', no warning; decided: warn, --fix adds .env*"; }

if [ $# -eq 0 ]; then set -- DR0 DR1 DR2 DR3 DR4 DR5 DR6 DR7 DR8 DR9 DR10; fi
for s in "$@"; do "$s"; done
echo; echo "================ summary: $pass ok, $fail mismatch  (scratch: $DEMO_ROOT) ================"
[ "$fail" -eq 0 ]
